// Generated by `tsir make:policy`. Verifies the `user.update` policy rule
// allows principals whose role grants `user.update` and denies everyone else.
import { describe, expect, test } from 'bun:test';

import { userUpdatePolicy, userUpdateRule } from './user-update.policy.ts';

describe('user.update policy', () => {
  test('is registered under the user:update ref', () => {
    expect(userUpdatePolicy[0]).toBe('user:update');
  });

  test('allows when the permission is granted', () => {
    const decision = userUpdateRule({
      principal: { subject: 'u_1' },
      data: undefined,
      permissions: new Set(['user.update']),
    });
    expect(decision.allowed).toBe(true);
  });

  test('denies when the permission is not granted', () => {
    const decision = userUpdateRule({
      principal: { subject: 'u_1' },
      data: undefined,
      permissions: new Set(),
    });
    expect(decision.allowed).toBe(false);
  });
});
